    public function getSourceContext(): Source
    {
        return new Source("{# Paires radio + label dans un flex (le layout Symfony « expanded » est plat sans div intermédiaire). #}
{% use \"form_div_layout.html.twig\" %}

{%- block choice_widget_expanded -%}
    <div {{ block('widget_container_attributes') }}>
        {%- for child in form %}
            <div class=\"harmony-lieu-segment-pair\">
                {{- form_widget(child) -}}
                {{- form_label(child, null, {translation_domain: choice_translation_domain}) -}}
            </div>
        {% endfor -%}
    </div>
{%- endblock choice_widget_expanded -%}
", "form/evenement_choice_layout.html.twig", "/Users/aziz/Downloads/symfony-etude/harmony-final/Esprit-PIWEB-3A24-2526-Harmonie-forum-communication/templates/form/evenement_choice_layout.html.twig");
